R = [record('pantheon-maddie-stellar-project','c0485','Pantheon — Maddie’s stellar simulation project','Pantheon','The active uploaded owner of the outer computational project',['cartoon','tv'],
 scope('Season-two Deep Time finale','The long-running stellar computation project before Maddie’s final return into a simulation','Maddie as the continuing active human-derived owner/resident of the outer project',['All simulated inhabitants as equally privileged owners','Temporary extracted research helpers as permanent residents','Passive genetic records','The ending’s restarted world as a settled post-work order'],proxy=True),
 'Maddie’s uploaded existence is sustained by a continuing stellar-powered computational project she owns and uses to reconstruct worlds. This is a deliberately tiny productive unit, not a claim that every simulated inhabitant receives an unconditional material floor. The outer resident has actual long-term computing and energy provision without earning a current physical wage. The strong guarantee estimate concerns that private self-provision, while remaining dependent on the functioning substrate rather than a universal citizenship right.\n\nEffective control belongs to Maddie, a human-derived mind. Becoming software does not make her an external AI ruler over herself. The project’s vast scale also does not turn its internal people into owners of the underlying machinery. Her reconstruction and investigation are sustained useful research, so this one-resident scope has a nonworking estimate of zero despite its freedom from wage dependence. Temporary helpers and countless inner-world persons are not added to that denominator. The final choice to re-enter a world changes her position and is not assigned the same abundance or control.',
 {'guarantees':-0.75,'control':0.05,'nonworking':0},
 {'guarantees':assessment(-0.75,[-1,-0.4],'medium','The continuing owner has actual stellar energy/computational provision without a current wage, but not a universal external entitlement.',p),
  'control':assessment(0.05,[0,0.15],'medium','Maddie owns and directs the outer infrastructure; she is a human-derived person rather than a separate autonomous AI provider.',p),
  'nonworking':assessment(0,[0,0],'medium','In the explicitly one-resident project scope, Maddie undertakes ongoing useful reconstruction/research. This is a role-based scope judgment, not a universe-wide census.',p)},
 1,p,[evidence('The active uploaded Maddie owns stellar computation and continuously uses it for reconstruction research.',p,'Matrioshka owner/construction description and Deep Time project explanation','secondary_tv_lore_reference')],
 ['A deliberately one-person ongoing production unit, with an explicit human-derived proxy.', 'The reader must not assign Maddie’s resource access to every inner simulated world.', 'Research counts as work even when wage dependence disappears.', 'No disputed exact construction date or stellar location is adopted.']),
 record('deva-memory-merit-society','c0492','Expelled from Paradise — DEVA’s memory-ranked digital society','Expelled from Paradise','Active human-derived DEVA citizens',['anime','movie'],
 scope('2014 animated film','The established digital society before Angela’s expulsion','Active human-derived citizens using DEVA resources',['Archived inactive persons as leisure residents','Physical Earth survivors','The prospective Genesis Ark community','Prose adaptation details as identical film evidence'],proxy=True),
 'DEVA sustains human minds as software within a computational environment, replacing ordinary bodily subsistence with provision through the platform. This is an actual inhabited society rather than a proposed upload. Its apparent abundance has a material limit: memory and opportunity are allocated by assessed contribution. Elite authorities decide what deserves resources, so automatic virtual provision does not create a secure equal claim to continued expansion or full citizenship. The guarantee estimate is correspondingly weak.\n\nThe council clearly concentrates authority, but the short checked sources do not fully resolve its members’ origin and effective relation to the system. The control coordinate therefore remains open rather than guessing between human-derived elite rule and external AI authority. Angela’s security work and other contributions remain real useful activity, even though their products are largely informational. Merit ranking is not a nonworking statistic, and inactive archives are not citizens enjoying leisure. Physical Earth and the proposed space voyage are separate arrangements and receive none of DEVA’s coordinates automatically.',
 {'guarantees':0.65,'control':None,'nonworking':None},
 {'guarantees':assessment(0.65,[0.2,1],'medium','Actual digital support is conditional and stratified through scarce memory and elite assessment of contribution; equal secure provision is not established.',d),
  'control':assessment(None,None,'low','Council power is concentrated, but the checked evidence does not settle the human-derived versus external-AI nature of decisive control.',d),
  'nonworking':assessment(None,None,'low','Security and other useful contribution continue; memory ranks and archive status are not a participation census.',d)},
 3,d,[evidence('DEVA hosts active digitized humans while authorities distribute scarce memory by merit.',d,'Official digital-society synopsis and two memory/contribution commentaries','official_synopsis_and_secondary_criticism')],
 ['Control remains unresolved and the regime label is provisional.', 'The memory-allocation analysis rests partly on secondary criticism.', 'Archived people are excluded from active participation.', 'The translated prose adaptation is not treated as the film.'],alternatives=[6])]
